def give_every_row_a_line(apps, schema_editor):
    """Every In-House Hours row is now a Section C line: a row that was "reference only"
    (no operation_code) gets the next free code, in table order."""
    InHouseHourRate = apps.get_model("reference", "InHouseHourRate")
    used = set(InHouseHourRate.objects.exclude(operation_code=None).values_list("operation_code", flat=True))
    for row in InHouseHourRate.objects.filter(operation_code__isnull=True).order_by("order", "id"):
        n = 1
        while f"c{n}" in used:
            n += 1
        row.operation_code = f"c{n}"
        row.save(update_fields=["operation_code"])
        used.add(row.operation_code)


